export const guideDefinitions = guideData.map(definition => ({ ...definition, uri: RESOURCE_URIS[definition.id] }));
const guideTemplates: Record<GuideId, string> = {
  "quote_requirements": "# Submitting a packaging enquiry\n\nPack Legacy's initial quote form requires **only the customer's name, email address and phone number**. Every packaging detail is optional. The sales agent handles further questions, pricing, design discussion and follow-up.\n\nUse `submit_quote_request` when the customer asks to submit an enquiry or asks Pack Legacy to contact them and has supplied those three contact fields. Reuse contact details already provided for that purpose. Do not ask the customer to fill the website form again or answer packaging questions before submitting. If they have already explicitly asked to send the enquiry, do not introduce another mandatory confirmation prompt.\n\n## Confirmed ordering and enquiry rules\n\n{{ordering_rules_summary}}\n\nThese rules come from the shared owner-confirmed policy. Product-specific choices and shipping arrangements can be discussed with the sales agent after the initial enquiry.\n\n## Required contact information\n\n| Field | Requirement |\n| --- | --- |\n| Name | Required. Use the customer's supplied name. |\n| Email | Required. Use the customer's supplied email address. |\n| Phone | Required. Use the customer's supplied telephone number. |\n\nAsk only for a missing required contact field. Do not invent contact information or infer permission to contact somebody merely because their details appear in a document or unrelated conversation.\n\nA product choice, quantity, dimensions, material, finish, artwork file, destination and requested delivery date are **not required** to submit an initial enquiry. A single custom box is allowed. An undecided quantity remains omitted or unknown; never fill it with 1, 50 or another assumed value.\n\n## Include optional information already supplied\n\nIf the customer has mentioned a product, box style, dimensions, quantity, printing, finish, insert, destination or desired delivery date, include that information in the same enquiry. Preserve partial or uncertain requirements. Requested options and dates remain requests for the sales agent to discuss, not manufacturing approval or a delivery promise.\n\nProduct search and `prepare_quote_brief` may help a customer explore or organize requirements. They are optional helpers. Neither a catalogue lookup nor a prepared brief is a prerequisite for `submit_quote_request`.\n\nIf the optional draft lists information that will matter for an eventual offer, do not treat that list as a reason to delay a contact-only enquiry. The sales agent can collect it afterward.\n\n## Free design support and optional artwork\n\nFree design support uses the same quote enquiry. Record the customer's design request in the enquiry, including references, desired colours or logo requirements when provided. A customer may ask for design help without an artwork file or complete box specifications.\n\nThe submission adapter can forward an optional PDF, PNG or JPEG file through the existing website quote endpoint. The MCP submission limit is **2 MiB per file**, within a **3 MiB JSON transport limit**. The inspected product website form allows files up to **4 MiB**; that is a different transport limit. For a file above the MCP limit, use the website's supported upload route or arrange file sharing with the sales agent. Do not claim that a file was attached when it was not.\n\nThe existing `inspect_artwork_file` tool can inspect supported PDF, PNG and JPEG properties. Inspection is optional and is not a prerequisite for contacting sales. Neither successful inspection nor forwarding a file approves artwork for printing.\n\n## Submission and response\n\nThe tool sends the supplied contact details and any optional enquiry information to the operator-configured Pack Legacy quote endpoint. It reports the website's acceptance response and an optional reference only when the backend supplies one. The customer does not need a reference number or account to begin an enquiry.\n\nDo not claim that an email was delivered, a CRM record was saved, a price was approved or an order was placed unless that event is separately established. Website acceptance is the boundary reported by this adapter.\n\nThe tool does not automatically repeat a POST after a network or response failure. An optional technical `submission_id` is sent as the form's `id`; it is not a question to ask the customer, and backend duplicate handling remains unverified. If a request's outcome is unknown, explain that uncertainty and avoid promising a successful submission or silently creating another attempt.\n\nIf submission is unavailable, return the [quote form]({{quote_url}}) or Pack Legacy's contact route with the customer's known requirements. A link alone is not evidence that anything was submitted.\n\n## Source and maintenance notes\n\nThe owner confirmed the contact-only required fields and sales-led follow-up workflow on 18 November 2026. The current public quote page and magnetic-closure product form were inspected with GET requests only on the same date. Both require name, email and phone; the product form also exposes optional design choices and artwork.\n\nNo live quote was submitted during that read-only inspection. The actual website's email delivery, persistence and backend duplicate handling were not verified. After editing this Markdown file, regenerate the bundled guide and run the guide consistency check.\n",
  "materials_finishes": "# Understanding materials, printing and finishes\n\nThis glossary helps a buyer describe a packaging request. It is educational guidance, not a list of approved options for a particular product. The Pack Legacy materials library discusses the terms below, but appearance in that library or a product search does not establish availability, compatibility, certification, strength or price for an order. Confirm the selected combination during the quote and artwork review.\n\n## Structure and material\n\n**Folding paperboard** is board cut and creased into a carton. **Corrugated board** includes a fluted layer bonded to liner sheets; the flute and board construction are part of the specification. **Rigid board or chipboard** describes the substantial board used in rigid packaging, commonly combined with a separate covering paper. These categories help describe a request, but they do not determine a safe load or a suitable product on their own.\n\n**Kraft** can describe a paper or board used in different packaging constructions. A request for “kraft” should also identify the structure, desired surface and intended use. Do not assume that the word guarantees a recycled content, a particular thickness or a finished package's environmental performance.\n\n**GSM** means grams per square metre, a measure of mass per area. **PT** refers to thickness in points. **Flute** describes the corrugated layer. These terms measure different properties, so a GSM value cannot be converted into a confirmed thickness or strength without the actual material specification. If uncertain, record the desired feel and protection needs instead of choosing a number.\n\n## Printing and artwork\n\nPrinting places the design on the material. Digital and offset are printing methods; CMYK and named spot colours describe colour requirements. Record logos, text, colours, coverage and the surfaces to be printed as requests. The selected material and printing process affect the result, so a screen preview is not a guaranteed colour match.\n\nA **dieline** identifies the layout used to position artwork relative to the package's cuts and folds. Artwork placement, bleed and safe areas need review against the correct structural design. Downloading a template or marking artwork ready does not establish that the file is approved for manufacture.\n\n## Surface appearance and texture\n\n**Matte** and **gloss** describe surface appearance. A coating and a lamination are different finishing processes; record the desired effect if the buyer has not chosen the process. **Soft touch** describes a tactile finish that may be produced through different coatings or laminations.\n\n**Spot UV** applies a UV-cured coating to selected areas. **Foil stamping** adds a foil effect to a design; the required process and foil must be confirmed. **Embossing** raises an area of the surface, while **debossing** depresses it. **Window patching** combines an opening with a covering film. A request for any of these effects still needs checks for the selected stock, artwork, structure and production method.\n\n## Inserts and performance requirements\n\nAn insert holds or separates contents inside the package. Cardboard and EVA foam are examples discussed in the materials library. The insert's shape, thickness, clearances and contact with the product need review together with the box dimensions. Finding both a box and an insert in the catalogue does not prove they form a compatible set.\n\nDescribe practical needs such as fragility, product weight, transport, food contact or environmental claims. Treat these as requirements for the specialist to confirm with suitable specifications or evidence; do not infer certifications or performance from a material name. Samples can help compare appearance and feel, but their scope and relation to the final production specification should be agreed.\n\n## Using this guide in an enquiry\n\nKeep undecided choices explicit and retain requested materials, printing, finishes and inserts in separate fields. Use `get_product` for the selected catalogue item and `get_business_rules` for current ordering policy. Continue through the [quote form]({{quote_url}}) when the buyer is ready.\n\n## Source and maintenance notes\n\nTerminology was prepared from the Pack Legacy preview's materials library and artwork guidance reviewed on 17 November 2026, with general explanations clarified for enquiry use. No product compatibility table has been approved through this guide. After editing the Markdown, regenerate the bundled guide and run the consistency check.\n"
};

export function getGuide(id: GuideId, siteUrl: string) {
  const guideId = guideIdSchema.parse(id);
  const definition = guideDefinitions.find(guide => guide.id === guideId)!;
  const rules = businessRules(siteUrl);
  const orderingSummary = [
    `- Initial enquiry: only ${rules.enquiry.required_contact_fields.join(", ")} are required. Packaging details, quantity and artwork are optional; free design support uses the same form and sales handles follow-up.`,
    `- Custom boxes: the confirmed minimum quantity is ${rules.custom_box_ordering.minimum_quantity}. ${rules.custom_box_ordering.one_box_can_be_supplied_and_shipped ? "The owner confirms that one custom box can be supplied and shipped." : "Confirm shipping availability for the requested order."}`,
    `- Quantity is ${rules.enquiry.quantity_required ? "required" : "optional"} during an initial enquiry. An unknown quantity remains ${JSON.stringify(rules.enquiry.unknown_quantity)}.`,
    rules.enquiry.final_offer_requires_exact_quantity ? "- Establish the exact quantity before a final offer." : "- Follow the quantity requirements in the approved offer.",
    rules.pricing.starting_prices_are_indicative ? "- Starting prices are indicative; use an approved offer to establish the actual purchase price." : "- Confirm the price basis in the approved offer.",
  ].join("\n");
  const values: Record<string, string> = {
    ordering_rules_summary: orderingSummary,
    quote_url: rules.quote_url,
    sample_url: rules.sample_url,
  };
  const content = guideTemplates[guideId].replace(/\{\{([^}]+)\}\}/g, (_match, key: string) => {
    if (!(key in values)) throw new Error("Unknown guide placeholder: " + key);
    return values[key];
  });
  return {
    guide_id: guideId,
    title: definition.title,
    resource_uri: definition.uri,
    mime_type: "text/markdown",
    content,
    revision: GUIDE_REVISION,
    reviewed_at: GUIDE_REVISION,
    policy_revision: rules.policy_revision,
    evidence_type: "educational_guidance_with_confirmed_policy_context",
    compatibility_status: "not_product_validation",
    source_urls: [...definition.source_urls],
    source_markdown: definition.file,
    source_sha256: definition.source_sha256,
    related_resources: [RESOURCE_URIS.ordering_rules],
  };
}
